from .executor_factory import ExecutorFactory
from taf.internal.core import camel_case


def CreatingExecutor(
        attr_name,
        executor_config_name="executor"):
    mixin_class_name = "Creating" + camel_case(attr_name) + "TypeExecutor"

    class CreatingExecutorTemplate(object):

        def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
            super(CreatingExecutorTemplate, self)._build_arguments(
                configuration=configuration,
                existing_arguments=existing_arguments,
                resulting_arguments=resulting_arguments)
            resulting_arguments[attr_name] = ExecutorFactory().create(
                configuration={'type': 'local'} if executor_config_name is None
                else configuration[executor_config_name],
                existing_arguments={})

    return type(mixin_class_name, (CreatingExecutorTemplate,), {})
